-- The compositor classifies physical holds; portal delivery latency must not
-- convert a short tap into a hold or reorder it behind the next chord.
advance(18000)
for _, duration in ipairs({325, 699}) do
  reload_bindings()
  local before = count("app:dictate-tap-cancel")
  local holds = count("release")
  keyboard(37, nil, 1)
  keyboard(133, nil, 1)
  bindings["CTRL + Super_L"]()
  advance(time + duration)
  keyboard(133, nil, 0)
  bindings["CTRL + Super_L"]()
  advance(time + 351)
  assert(count("app:dictate-tap-cancel") == before + 1, "short hold did not cancel as a tap")
  assert(count("release") == holds, "short hold became a long hold")
  keyboard(37, nil, 0)
  advance(time + 500)
end

